def header(active=''):
 def link(path,title):return f'<a href="/{path}/"'+(' aria-current="page"' if active==path else '')+f'>{title}</a>'
 return '<a class="skip" href="#main">Skip to content</a><header><a class="wordmark" href="/" aria-label="Spacecraft home"><span class="wordmark-art"><img src="/assets/spacecraft-wordmark-v3.png" width="2172" height="724" alt="spacecraft"></span><small>WORKPLACE DESIGN & BUILD</small></a><nav aria-label="Main navigation">'+''.join(link(p,t) for p,t in [('about-us','About us'),('services','What we do'),('projects','Spaces'),('blogs','Journal')])+f'</nav><a class="nav-contact" href="/contact-us/">Let’s talk <span>↗</span></a><button class="menu" aria-expanded="false" aria-controls="mobile-nav">Menu <span>＋</span></button></header><div id="mobile-nav" hidden>'+''.join(link(p,t) for p,t in [('about-us','About us'),('services','What we do'),('projects','Space studies'),('how-we-work','How we work'),('blogs','Journal'),('locations','Locations'),('career','Careers'),('become-a-partner','Become a partner'),('contact-us','Get in touch')])+'</div>'

def footer():
 groups=[('Explore',[('about-us','About us'),('why-space-craft','Why Space Craft'),('how-we-work','How we work'),('projects','Space studies')]),('What we do',[('services/workplace-planning','Workplace planning'),('services/interior-design','Interior design'),('services/build-and-fit-out','Build & fit-out')]),('Ideas & people',[('blogs','Design journal'),('web-stories','Quick reads'),('career','Careers'),('become-a-partner','Partner with us')]),('More',[('locations','Locations'),('contact-us','Contact'),('all-pages','All pages'),('privacy-policy','Privacy'),('terms-and-conditions','Terms')])]
 return '<footer class="site-footer"><div class="footer-top"><a class="wordmark" href="/"><span class="wordmark-art"><img src="/assets/spacecraft-wordmark-v3.png" width="2172" height="724" alt="spacecraft"></span><small>SPACE FOR WHAT COMES NEXT.</small></a><address>'+E(ADDRESS)+f'<br><a href="{MAP}" target="_blank" rel="noopener">Find us on the map ↗</a></address></div><div class="footer-groups">'+''.join('<div><h2>'+t+'</h2>'+''.join(f'<a href="/{p}/">{n}</a>' for p,n in links)+'</div>' for t,links in groups)+'</div><div class="footer-base"><p>© 2026 Space Craft · Website prototype</p><p>Illustrative photography. Concepts are not completed projects.</p><a href="#" aria-label="Back to top">Back to top ↑</a></div></footer>'

def crumb(label,parent=None):return '<div class="breadcrumbs"><a href="/">Home</a><span>/</span>'+ (f'<a href="/{parent[0]}/">{parent[1]}</a><span>/</span>' if parent else '')+f'<span>{E(label)}</span></div>'
def cta(title='Your next chapter starts here.',text='Tell us what you want your workplace to make possible.'):
 return f'<section class="page-cta"><div><span class="eyebrow">LET’S MAKE SPACE</span><h2>{title}</h2><p>{text}</p></div><a class="button light" href="/contact-us/">Start your project brief <span>↗</span></a></section>'
def photo(name,alt,cls='editorial-photo'):
 return f'<figure class="{cls}"><img src="/assets/{name}.jpg" alt="{E(alt)}" loading="lazy"><figcaption>Illustrative photography · Unsplash · Not a Space Craft project</figcaption></figure>'
def hero(kicker,title,description,image='studio',label=None):
 return f'<section class="page-hero"><div class="page-hero-copy"><div class="eyebrow">{E(kicker)}</div><h1>{title}</h1><p>{description}</p><a class="text-link" href="/contact-us/">Let’s talk about your space <span>↗</span></a></div>'+photo(image,label or 'Illustrative workplace interior','page-hero-photo')+'</section>'
def cards(items,cls='page-card-grid'):
 return f'<div class="{cls}">'+''.join(f'<a class="page-card" href="/{path}/"><span class="eyebrow">{E(tag)}</span><h3>{title}</h3><p>{desc}</p><span class="card-arrow">↗</span></a>' for path,title,desc,tag in items)+'</div>'
def write(path,title,body,kind='Page',active='',desc=None):
 path=path.strip('/');(D/path).mkdir(parents=True,exist_ok=True)
 description=desc or re.sub('<[^>]+>','',title)+' — Space Craft workplace design and build.'
 s=f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{E(description,quote=True)}"><meta name="theme-color" content="#c42e24"><title>{E(re.sub("<[^>]+>","",title))} — Space Craft</title><link rel="stylesheet" href="/style.css"><link rel="stylesheet" href="/pages.css"><link rel="canonical" href="{BASE}/{path}/"></head><body>'+header(active)+f'<main id="main">{body}</main>'+footer()+'<script src="/pages.js"></script></body></html>'
 s=re.sub(r'(href="[^"]*#[^"]*)/"',r'\1"',s)
 (D/path/'index.html').write_text(s)
 records.append({'path':'/'+path+'/','title':re.sub('<[^>]+>','',title),'kind':kind})
def form(kind='project',location=''):
 extra=''
 if kind=='partner':extra='<label>Your specialism<select name="specialism"><option>Architecture & design</option><option>Contracting & fit-out</option><option>Furniture & materials</option><option>Building services</option><option>Other</option></select></label>'
 if kind=='career':extra='<label>Your area of interest<select name="interest"><option>Design & planning</option><option>Project coordination</option><option>Procurement & sourcing</option><option>Other</option></select></label>'
 return f'<form class="demo-form" data-kind="{kind}"><div class="eyebrow">DEMO / CREATE YOUR BRIEF</div><div class="form-row"><label>Your name *<input name="name" required maxlength="100" autocomplete="name" placeholder="Full name"></label><label>Email *<input type="email" name="email" required maxlength="200" autocomplete="email" placeholder="you@company.com"></label></div><div class="form-row"><label>Company<input name="company" maxlength="150" autocomplete="organization" placeholder="Company / studio"></label><label>Location<input name="location" maxlength="150" value="{E(location,quote=True)}" placeholder="City / area"></label></div>'+extra+('<div class="form-row"><label>Project scope<select name="service"><option>Explore my options</option><option>Workplace planning</option><option>Interior design</option><option>Build & fit-out</option></select></label><label>Approximate area<select name="area"><option>Not sure yet</option><option>Under 2,000 sq ft</option><option>2,000–5,000 sq ft</option><option>5,000–10,000 sq ft</option><option>Over 10,000 sq ft</option></select></label></div>' if kind=='project' else '')+'<label>'+('Tell us about your plans' if kind=='project' else 'A little about you and your work')+' *<textarea name="brief" required minlength="10" maxlength="4000" rows="4" placeholder="Share a little context…"></textarea></label><p class="form-explainer">Demo form: your details stay in this browser tab. Nothing is submitted to Space Craft or saved on a server.</p><button class="button dark" type="submit">Create demo '+('inquiry' if kind=='project' else 'profile')+' <span>↗</span></button><div class="demo-result" role="status" hidden></div></form>'

# Main company and service pages.
write('about-us','A better place to do your best work.',crumb('About us')+hero('ABOUT SPACE CRAFT','People first.<br>Space follows.','Space Craft is a workplace design and build concept centred on a simple question: what does your team need from its space?','details')+'<section class="section split-section"><div><div class="eyebrow">OUR POINT OF VIEW</div><h2>Good design begins<br>with listening.</h2></div><div><p class="lead-copy">The right office makes everyday work feel a little more considered. It gives people somewhere to concentrate, connect and belong.</p><p>Our starting point is your brief: the tasks your team does, the moments that matter, the constraints you need to work within. From there, planning, interiors and fit-out become parts of the same conversation.</p><p>Space Craft is taking shape. This prototype sets out the approach; it does not present a history of completed projects or a published leadership team.</p></div></section><section class="section tone-paper"><div class="eyebrow">WHAT GUIDES THE WORK</div><h2>Clarity in every decision.</h2>'+cards([('how-we-work','Listen before drawing.','Understand the people and priorities before settling on a plan.','01 / PEOPLE'),('services/interior-design','Make the details matter.','Consider light, sound, circulation and materials alongside the visual story.','02 / PURPOSE'),('contact-us','Keep the brief visible.','Discuss scope, assumptions and changes as the project takes shape.','03 / CLARITY')])+'</section>'+cta(),active='about-us')
services=[('workplace-planning','Workplace planning','A clear brief.<br>A stronger starting point.','Understand how your team works before deciding how your office should look.','studio',[('Discover the working day','Map headcount, attendance, focused tasks, collaborative work, visitor journeys and the practical needs of different teams.'),('Test the layout','Explore workstation positions, meeting settings, storage and circulation together. Check what fits without reducing every decision to desk count.'),('Make the brief useful','Agree the priorities, constraints and questions still to resolve. A useful brief makes later design and budget decisions easier to assess.')]),('interior-design','Interior design','Your identity.<br>In every detail.','Bring layout, light, colour and materials together around the way your workplace needs to feel and function.','details',[('Set a visual direction','Use a small set of references and a material palette to connect the space with your brand. Discuss what is functional, what is expressive and where the two meet.'),('Design the everyday experience','Consider lighting, acoustics, seating, privacy and the route through the office. Look beyond a single hero view to the places people use throughout the day.'),('Resolve the specifications','Review samples, dimensions and maintenance needs before finalising finishes. Record decisions so that procurement and delivery have a shared reference.')]),('build-and-fit-out','Build & fit-out','From the drawing.<br>To the everyday.','Connect the design intent with a practical conversation about scope, coordination and the finishing details.','meeting',[('Define the work','Turn the agreed design into a scope with inclusions, exclusions and dependencies. Discuss building permissions and specialist input before setting a programme.'),('Coordinate the decisions','Bring materials, furniture, building services and site activities into one working sequence. Record changes and confirm their implications before proceeding.'),('Review the details','Plan walkthroughs, snag reviews and handover information as part of the work. Agree what completion means for the space and the people moving into it.')])]
write('services','What we do.',crumb('What we do')+hero('CONNECTED WORKPLACE THINKING','From first thought.<br>To final detail.','Choose support for the stage you are at, or start with the whole workplace brief.','collaborate')+'<section class="section">'+cards([('services/'+s[0],s[1],s[3],f'0{i+1} / SERVICE') for i,s in enumerate(services)])+'</section>'+cta(),active='services')
for slug,title,headline,intro,img,sections in services:
 body=crumb(title,('services','What we do'))+hero('WHAT WE DO / '+title.upper(),headline,intro,img)+'<section class="section service-detail"><div><div class="eyebrow">THE CONVERSATION</div><h2>Start with what<br>your space needs.</h2><p>Scope, deliverables and availability are discussed for each brief.</p></div><div>'+''.join(f'<article class="numbered-item"><span>0{i+1}</span><h3>{h}</h3><p>{p}</p></article>' for i,(h,p) in enumerate(sections))+'</div></section><section class="section tone-paper"><div class="eyebrow">COME PREPARED</div><h2>A useful first conversation.</h2><div class="checklist"><p>✓ A floor plan or approximate area</p><p>✓ Team size and working patterns</p><p>✓ Your priorities and non-negotiables</p><p>✓ A budget range and desired move date</p></div></section>'+cta()
 write('services/'+slug,title,body,'Service','services')
process=[('Understand','Start with people, plans and constraints.','Share the floor plan, headcount, working patterns and priorities. Clarify who makes decisions, what budget is available and which dates are fixed.','A shared brief and a list of open questions.'),('Shape','Explore the right possibilities.','Compare layouts and a visual direction. Think through focus, collaboration, storage, visitors and the practical condition of the existing space.','A direction to develop, with assumptions recorded.'),('Resolve','Bring scope and detail together.','Review material samples, furniture, lighting and building services with the appropriate specialists. Confirm scope, dependencies and change decisions.','A clearer basis for pricing, coordination and delivery.'),('Create','Turn decisions into a working space.','Coordinate the agreed work, review progress and keep decisions visible. Discuss walkthroughs, handover information and any final items before moving in.','A reviewed space and an agreed handover checklist.')]
write('how-we-work','A clear path. A shared vision.',crumb('How we work')+hero('THE SPACE CRAFT APPROACH','Less guesswork.<br>More common ground.','An office project has many moving parts. Keep people, design and delivery connected from the beginning.','meeting')+'<section class="section process-page">'+''.join(f'<article><span class="step-number">0{i+1}</span><div><div class="eyebrow">{label.upper()}</div><h2>{h}</h2><p>{p}</p><aside><strong>The useful outcome</strong>{out}</aside></div></article>' for i,(label,h,p,out) in enumerate(process))+'</section>'+cta())
write('why-space-craft','Space that earns its place.',crumb('Why Space Craft')+hero('WHY SPACE CRAFT','A workplace.<br>With a reason.','A compelling space is more than a photograph. It should make the everyday work of your team feel considered.','workplace')+'<section class="section">'+cards([('services/workplace-planning','Built around real work.','Plan for actual attendance, individual tasks and moments of collaboration.','PEOPLE'),('how-we-work','A shared line of sight.','Keep the brief, design decisions and scope connected as the conversation develops.','CLARITY'),('services/interior-design','Details with purpose.','Let material, colour, light and sound support the experience of the space.','DESIGN')])+'</section><section class="section tone-paper"><div class="eyebrow">WHAT YOU CAN EXPLORE HERE</div><h2>The approach, honestly presented.</h2><p class="lead-copy narrow">This site shows Space Craft’s intended workplace approach and illustrative space studies. Project credentials, client references, delivery locations and firm commitments should be confirmed directly for your brief.</p></section>'+cta())
# Concepts replace competitor portfolio claims.
concepts=[('focus-and-flow','A little space to focus.','Focus & flow','studio','A workplace direction for teams that need quiet concentration alongside everyday collaboration.','Locate individual work away from busy circulation routes. Pair workstations with a small number of enclosed settings for calls and focused tasks.',[('Work settings','Individual workpoints, quiet rooms and shared touchdown surfaces.'),('Material direction','Soft neutrals, practical work surfaces and restrained visual detail.'),('Questions to test','Where does distraction happen? How many private settings are genuinely needed?')]),('a-place-to-connect','A reason to come together.','Connection & culture','workplace','An inviting shared heart for the office, where informal conversations have somewhere to happen.','Make the shared space easy to find and comfortable to use. Mix short-stay settings with seating that supports a longer conversation.',[('Work settings','An arrival lounge, an informal team table and small meeting corners.'),('Material direction','Warm timber, tactile upholstery and a considered accent colour.'),('Questions to test','Who uses the space, at what times, and how does it sit beside quieter work?')]),('room-to-grow','Built for your next chapter.','Change & growth','collaborate','A direction for a team whose office needs to adapt as people and working patterns change.','Start with the parts that need to stay fixed, then identify the settings that can change. Avoid treating every future possibility as an immediate construction requirement.',[('Work settings','Flexible team areas, shared support rooms and adaptable furniture.'),('Material direction','A durable base palette with replaceable, reusable elements.'),('Questions to test','What might change in a year? Which decisions would be expensive to reverse?')])]
project_cards=''.join(f'<a class="study-card" href="/projects/{s}/"><div><img src="/assets/{img}.jpg" alt="Illustrative workplace concept: {E(tag)}" loading="lazy"><span>ILLUSTRATIVE SPACE STUDY</span></div><h3>{h}</h3><p>{tag} <b>↗</b></p></a>' for s,h,tag,img,*_ in concepts)
write('projects','Spaces for different ways of working.',crumb('Space studies')+hero('SPACE STUDIES / CONCEPTS','Different teams.<br>Different possibilities.','Explore three starting points for a workplace conversation. These are illustrative concepts, not Space Craft client projects.','collaborate')+'<section class="section"><div class="study-grid">'+project_cards+'</div></section>'+cta(),active='projects')
for slug,h,tag,img,intro,paragraph,sections in concepts:
 write('projects/'+slug,h,crumb(tag,('projects','Space studies'))+hero('ILLUSTRATIVE SPACE STUDY / '+tag.upper(),h,intro,img)+'<section class="section split-section"><div><div class="eyebrow">THE DESIGN QUESTION</div><h2>What should this<br>space make possible?</h2></div><div><p class="lead-copy">'+paragraph+'</p><p class="notice">Concept study only. Photography is illustrative. No client, completed location, project size or delivery result is claimed.</p></div></section><section class="section tone-paper">'+cards([('contact-us',a,b,'CONCEPT NOTES') for a,b in sections])+'</section>'+cta('Make it work for your team.'),'Concept','projects')
# Contact, careers and partnership journeys.
write('contact-us','Let’s make space.',crumb('Contact us')+'<section class="section contact-page"><div><div class="eyebrow">GET IN TOUCH</div><h1>Your next move.<br><em>Starts here.</em></h1><p class="lead-copy">A new office. A fresh start. A space that finally fits. Tell us what you have in mind.</p><div class="address-card"><span class="eyebrow">SPACE CRAFT / BENGALURU</span><address>'+E(ADDRESS)+f'</address><a class="text-link" href="{MAP}" target="_blank" rel="noopener">View map & directions <span>↗</span></a></div><p class="small-note">Use the demo form to prepare a downloadable brief. This prototype does not send messages or offer a confirmed appointment.</p></div>'+form()+'</section>')
write('career','Make space for meaningful work.',crumb('Careers')+hero('PEOPLE / CAREERS','Good spaces.<br>Start with people.','Interested in workplace design, thoughtful detail and the process of bringing a brief to life? Explore where your skills could fit.','team')+'<section class="section split-section"><div><div class="eyebrow">A TEAM TAKING SHAPE</div><h2>Curiosity.<br>Care. Clarity.</h2></div><div><p class="lead-copy">We are setting out a way of thinking about workplace design that values listening, practical decisions and a well-considered result.</p><p>No live vacancies are listed in this prototype. You can explore the disciplines below and prepare a demo expression of interest.</p><a class="text-link" href="/job-openings/">Explore disciplines <span>↗</span></a></div></section>'+cta('Bring your perspective.','Explore the disciplines and create a demo profile to introduce your interests.'))
write('job-openings','Find your place in the process.',crumb('Opportunities',('career','Careers'))+'<section class="section"><div class="eyebrow">CAREER EXPLORATION</div><h1>Different skills.<br><em>A shared purpose.</em></h1><p class="lead-copy narrow">These are areas of interest, not advertised vacancies. There are no confirmed open roles in this prototype.</p>'+cards([('job-openings/#interest','Design & planning','Turn working patterns and practical constraints into considered layouts and visual directions.','DISCIPLINE'),('job-openings/#interest','Project coordination','Help connect scope, decisions, programme and the details of delivery.','DISCIPLINE'),('job-openings/#interest','Sourcing & materials','Think through products, samples, specifications and long-term care.','DISCIPLINE')])+'</section><section id="interest" class="section split-section tone-paper"><div><div class="eyebrow">EXPRESS YOUR INTEREST</div><h2>Tell your story.</h2><p>Prepare a demo profile to keep or share yourself. No application is submitted.</p></div>'+form('career')+'</section>')
write('become-a-partner','Better work, together.',crumb('Become a partner')+hero('DESIGNERS / MAKERS / SPECIALISTS','Bring your craft.<br>Build a connection.','A considered workplace draws on different skills. Explore a potential conversation around design, materials, furniture or fit-out.','details')+'<section class="section">'+cards([('become-a-partner/#partner-form','Design collaborators','Architecture, interiors, workplace planning and specialist design perspectives.','01 / DESIGN'),('become-a-partner/#partner-form','Makers & suppliers','Furniture, materials, finishes and products with clear specifications.','02 / MATERIALS'),('become-a-partner/#partner-form','Delivery specialists','Fit-out, building services and the details that connect a plan to a place.','03 / DELIVERY')])+'</section><section id="partner-form" class="section split-section tone-paper"><div><div class="eyebrow">A FIRST INTRODUCTION</div><h2>Tell us what<br>you do well.</h2><p>Share your specialism, location and the kind of work you are interested in. No supplier approval, appointment or commercial terms are offered through this demo.</p></div>'+form('partner')+'</section>')
# Original educational content library. Each topic has concrete design considerations, questions and a practical exercise.
TOPICS={
'planning':('Planning & layouts','studio','Build the plan around the working day.', [('Map activity before assigning desks','Write down the tasks people perform, how often teams overlap and when visitors arrive. A desk count alone will not reveal the need for private calls, project tables or storage.'),('Make the routes legible','Sketch the path from entry to reception, work areas, meeting settings and shared support. Test the layout with furniture drawn to scale, doors in use and accessible routes considered.'),('Balance density with choice','Compare a focused-work setting with the busiest collaborative setting. Where they meet, think about sound, sightlines and transitions rather than using one open area for every task.')],['Record attendance patterns before fixing seat numbers.','Mark quiet work, conversations and visitor movement separately.','Test the layout with the people who will use it.']),
'ceiling':('Ceilings & services','meeting','Treat the ceiling as part of the whole room.', [('Start with the services above it','A ceiling has to work around lighting, ventilation, fire services and access requirements. Establish the existing constraints and coordinate specialist advice before choosing a finished pattern.'),('Compare systems by use','A suspended grid may offer practical access; a continuous finish can create a quieter visual field. Review repairability, acoustic performance and the effect on available height, using product-specific information.'),('Coordinate the room below','Align the ceiling and lighting with the furniture arrangement, not just the outline of the room. Recheck the setting when partitions, meeting tables or workstations move.')],['Survey existing height and service locations.','Ask how maintenance access will be provided.','Review a sample and a reflected ceiling plan together.']),
'walls':('Walls & materials','details','Choose a wall finish for more than the photograph.', [('Give each surface a job','A wall can guide visitors, provide writable space, support acoustic treatment or carry a small moment of brand identity. Decide what it needs to do before adding decorative layers.'),('Check the everyday contact points','Review cleanability, edges, joints and likely wear around desks and circulation routes. Compare physical samples in the actual light rather than relying only on a small screen image.'),('Resolve what sits behind it','Sockets, access panels, doors and equipment can interrupt a seemingly simple elevation. Coordinate these details early so the finish does not create an obstacle to maintenance.')],['Name the functional purpose of each proposed finish.','Compare samples beside adjacent materials.','Record cleaning and replacement requirements.']),
'colour':('Colour & identity','details','A useful palette starts with context.', [('Read the light first','Daylight, artificial light and neighbouring surfaces all affect colour. Review sample boards at different times of day and beside the materials that will actually be installed.'),('Set a base and an accent','A restrained base can let furniture, signage or a focused area carry the stronger colour. Consider where contrast helps orientation and where too much visual activity may become distracting.'),('Test the complete composition','Look at paint, flooring, upholstery and joinery together. Colours that seem balanced in isolation can compete once combined. Let the intended use of each area guide the final balance.')],['Make one palette board for the whole space.','Test colour on a larger sample in situ.','Use readable contrast for signs and essential information.']),
'reception':('Arrival & reception','workplace','Make the first few minutes feel straightforward.', [('Follow the visitor journey','Think through finding the entrance, checking in, waiting and moving to a meeting. Make the next step clear without asking a visitor to cross private working areas.'),('Size the setting to actual use','Estimate the number of people who may arrive together and the support they need. A generous reception desk is not a substitute for suitable waiting seats, an accessible approach or a place for bags.'),('Express identity with restraint','A considered sign, a material or a focused colour moment may tell the brand story more effectively than filling every wall. Check the view from both the entrance and the seated waiting position.')],['Walk through an unfamiliar visitor’s route.','Test seating and desk dimensions at full scale.','Keep sign-in information and private documents protected.']),
'cabin':('Cabins & privacy','studio','Plan for the work, not just the title on the door.', [('List the activities inside','An enclosed room may need to support focused work, confidential calls, short meetings and occasional presentations. Prioritise the actual mix before choosing the desk and storage.'),('Balance enclosure and connection','Position doors and glazing with attention to privacy and the wider office. Visual openness does not automatically provide speech privacy; review acoustic requirements separately.'),('Test furniture as a setting','Draw the desk chair in use, visitor seats pulled out and cupboard doors open. These checks expose conflicts that a neat furniture outline can hide.')],['Agree the real purpose and occupancy of the room.','Check speech privacy and glare on screens.','Test furniture access and daily movement.']),
'meetings':('Meeting & conference spaces','meeting','Design for everyone in the conversation.', [('Start with the meeting types','Separate short discussions, long workshops and hybrid calls in the brief. The right setting depends on duration, attendance, privacy and the equipment people need to use.'),('Check the view from every seat','Screens, cameras, writing surfaces and presentation positions should work together. Avoid assuming that a long table automatically offers an equal experience to every participant.'),('Treat sound and air as design inputs','Review room acoustics, service requirements and likely occupancy with the relevant specialists. A good-looking enclosed room still needs to support conversation and regular use.')],['List the equipment and connections people need.','Check sightlines and camera framing from every seat.','Allow for furniture movement and maintenance access.']),
'furniture':('Furniture & workpoints','studio','Judge furniture as a working tool.', [('Define the task and the user','Consider the duration of use, range of activities and people sharing the setting. Review adjustable options and test samples rather than choosing solely from a photograph.'),('Check the whole workpoint','The desk, chair, monitor position, power and storage function together. Test the configuration with the equipment and accessories that people actually use.'),('Plan for care and change','Ask about warranty terms, spare parts, repair and cleaning. A furniture decision should consider the years of use ahead as well as the initial purchase.')],['Trial a representative workpoint with users.','Confirm dimensions, power access and cable routes.','Record care instructions and replacement options.']),
'nature':('Nature & workplace','collaborate','Bring nature in with a plan for its care.', [('Choose conditions before plants','Assess daylight, watering access, available space and responsibility for maintenance. Match plant choices to the actual setting with help from an appropriate supplier.'),('Think beyond a green feature','Natural materials, views and access to daylight can form part of the same conversation. Keep circulation clear and consider the people who may have sensitivities to scent, pollen or maintenance products.'),('Make upkeep part of the design','Plan drainage, containers and cleaning before installation. A simple, well-maintained planting scheme may serve the workplace better than a complex feature with no clear owner.')],['Map daylight and maintenance access.','Assign responsibility for ongoing care.','Keep plants clear of work surfaces and escape routes.']),
'budget':('Budget & project scope','details','A useful budget begins with a defined scope.', [('Break the brief into work packages','Separate building work, services, finishes, furniture, equipment and professional input. State what is already provided by the building and what must be added or replaced.'),('Compare like with like','A single per-square-foot figure can conceal major differences in scope and specifications. Ask for inclusions, exclusions, quantities, assumptions and the treatment of changes.'),('Choose where to prioritise','Identify what must work from day one and what can be phased. Discuss contingency and project dependencies before reducing every product specification to reach a target figure.')],['Bring the measured area and existing condition information.','Separate must-haves from optional upgrades.','Confirm a project-specific estimate before making commitments.']),
'acoustics':('Sound & concentration','meeting','Plan for the sound of the working day.', [('Separate sources and listeners','Identify conversations, calls, equipment and movement that may disturb focused work. Start with zoning before asking a single finish or furniture item to solve every sound issue.'),('Distinguish absorption from isolation','Reducing reverberation inside a room is different from stopping sound travelling between rooms. Ask an acoustic specialist which problem needs solving and what performance is appropriate.'),('Coordinate the small gaps','Doors, glazing, ceilings and service penetrations can affect the final result. Review the assembled room and its connections rather than relying on one product rating.')],['Map noisy and quiet activities.','Describe the required privacy in plain language.','Check details and performance with a specialist.']),
'small':('Small spaces','studio','A small office needs clear priorities.', [('Protect the essential functions','Decide what must happen within the space and which activities can share a setting at different times. Avoid adding a nominal room for every function if none will work comfortably.'),('Draw storage and circulation honestly','Small layouts can look generous when storage, doors and chair movement are left out. Include these from the start and test common tasks at a realistic scale.'),('Choose adaptable elements carefully','Movable furniture can support change, but only when it has somewhere to move. Keep a clear reset plan and allow storage for anything that is used occasionally.')],['Rank the most important daily activities.','Measure furniture instead of estimating from images.','Check the layout during its busiest likely moment.']),
'brand':('Brand & expression','details','Let the space tell a coherent story.', [('Translate values into behaviours','Ask what the business wants people to experience: clarity, openness, craft, energy or calm. Connect these words to planning and material decisions rather than applying them only as slogans.'),('Choose a few deliberate moments','Arrival, shared spaces and meeting settings can carry identity in different ways. Let colour, typography and materials relate without requiring every corner to look the same.'),('Keep useful information readable','Brand expression should work alongside wayfinding, room names and essential signs. Review visibility and contrast from the positions where people actually need to read them.')],['Write a short spatial brief for the brand.','Test the palette and signage as one system.','Prioritise useful information over decorative messaging.']),
'renovation':('Fit-out & renovation','meeting','Understand the existing space before changing it.', [('Survey before setting the scope','Record the condition of the space, fixed services and any building requirements. Discuss which elements can be retained, adapted or removed before developing a new finish scheme.'),('Make dependencies visible','Some work needs approval, specialist coordination or a sequence of activities. Discuss these dependencies when planning the programme rather than treating the desired date as the only input.'),('Plan the move and the handover','If the office remains in use, consider phasing, access and disruption. Agree review points, snagging and the information needed to operate the space after completion.')],['Gather existing drawings and building requirements.','Record what stays and what changes.','Discuss access, phasing and handover with the project team.']),
'wellbeing':('Comfort & inclusion','collaborate','Design for a range of people and working needs.', [('Ask people what gets in the way','Invite input on distractions, access, comfort and the settings people cannot currently find. A workplace brief should allow different experiences to be heard.'),('Offer sensible choices','A combination of quiet settings, collaborative areas and comfortable shared space can support different tasks. Discuss lighting, sound and furniture with users and relevant specialists.'),('Keep design in perspective','A physical space can support everyday comfort, but it cannot replace healthy management practices or professional support. Avoid treating a finish, colour or layout as a guaranteed wellbeing outcome.')],['Include different users in the brief.','Review accessibility throughout the journey.','Treat user feedback as a design input, not a promise of a measured outcome.']),
'flexible':('Hybrid & adaptable work','collaborate','Plan around the patterns, not the label.', [('Understand attendance over time','Look beyond average attendance to days when teams overlap, visitors arrive or projects bring people together. Shared seats need an operating plan as well as a furniture plan.'),('Support the reason to be there','Decide which activities benefit from being together and which need concentration or privacy. Give those activities appropriate settings instead of making the whole office uniformly collaborative.'),('Make change easy to manage','Movable furniture, shared storage and clear room-use conventions can help. Assign responsibility for reset and upkeep so flexibility does not become daily uncertainty.')],['Map peak and typical attendance separately.','Test a shared-seat day from arrival to departure.','Agree storage and reset conventions.']),
'lighting':('Light & atmosphere','studio','Consider the light people actually work in.', [('Combine daylight and task needs','Look at window positions, screens and the time of day each space is used. Plan blinds or shading alongside electric lighting so that brightness and glare can be managed together.'),('Give settings appropriate control','A workstation, a video-call room and an arrival lounge may need different lighting responses. Review the intended tasks with a lighting specialist rather than applying one decorative treatment everywhere.'),('Test finishes under the chosen light','Material colours and reflections change with the light source. Sample the complete combination before committing to a finish schedule.')],['Locate screens in relation to windows.','Review control and maintenance requirements.','Test materials under representative lighting.']),
'style':('Style & material direction','details','Use a style as a starting point, not a formula.', [('Name what you want from the reference','When an image appeals to you, identify why: the light, proportions, texture, restraint or sense of openness. Translate those qualities into your own brief rather than copying the whole room.'),('Balance character with daily use','An exposed structure, pale finish or highly polished surface has practical implications. Review cleaning, durability, glare and sound alongside the intended look.'),('Build a coherent material family','A small group of related finishes can make the space feel connected. Test the transitions between reception, work areas and enclosed rooms so that the story remains consistent.')],['Choose references for specific qualities.','Test durability and maintenance assumptions.','Review samples as a connected palette.']),
'culture':('Teams & workplace culture','team','Let the workplace support the way people work together.', [('Ask which moments matter','Consider onboarding, team catch-ups, private conversations and cross-team work. Identify where the current setting makes these activities harder than they need to be.'),('Give shared settings a clear purpose','A breakout room or communal table works best when people understand how it can be used. Discuss expectations around calls, informal meetings, food and focused work.'),('Review the lived experience','Invite feedback after people have used a setting. Small adjustments to furniture, guidance or booking rules may help more than adding another decorative feature.')],['Include team routines in the brief.','Agree practical use conventions.','Plan a feedback conversation after the move.']),
'technology':('Technology & design tools','meeting','Let tools support a clearer decision.', [('Define the question first','A digital plan, visualisation or AI-assisted exploration should help answer a specific question about layout, scale or direction. A polished image is not evidence that the space has been resolved.'),('Check the underlying information','Verify dimensions, product availability, services and the buildability of any visual proposal. Review automated suggestions with the appropriate design or technical specialist.'),('Keep a decision record','Capture what has been agreed and what is still illustrative. This helps avoid treating an early visual as a final specification or a commitment about delivery.')],['Name the decision the tool is helping with.','Verify dimensions and technical assumptions.','Distinguish visual exploration from construction information.']),
'pantry':('Pantries & shared amenities','collaborate','Give everyday breaks a practical place.', [('Map use at the busiest time','Consider how many people will prepare drinks, heat food, queue or sit down at once. Separate the active preparation route from places intended for conversation or a quiet break.'),('Coordinate the services','Water, drainage, power, ventilation and cleaning need to be part of the early brief. Confirm specialist and building requirements before fixing joinery or equipment positions.'),('Plan storage and care','Allow for consumables, waste sorting and the items that accumulate around shared facilities. Assign a practical maintenance and cleaning routine.')],['List the equipment and busiest-use scenario.','Review service and cleaning access.','Keep food preparation separate from focused work.']),
'cultural':('Personal preferences & workplace','details','Make room for preferences with a clear brief.', [('Discuss meaning without promising outcomes','Some teams want cultural, seasonal or personal references within the office. Treat these as preferences to explore, without presenting a direction, object or plant as a guarantee of prosperity or health.'),('Keep practical needs visible','Circulation, access, safety and comfort still need to guide the plan. Talk through any conflicts between a preferred arrangement and the needs of the people using it.'),('Choose reversible expressions','A movable object, artwork or seasonal display may offer an appropriate way to express a preference. Plan storage and keep shared settings inclusive.')],['Record preferences as part of the brief.','Separate personal meaning from measurable design requirements.','Keep access and essential signs clear.']),
'selection':('Choosing a design partner','meeting','Compare the process as carefully as the proposal.', [('Bring the same brief to each conversation','Share the measured area, building condition, intended occupancy, budget assumptions and desired scope. Different inputs make proposals difficult to compare.'),('Ask for relevant evidence','Discuss directly relevant project examples, the people involved and the proposed deliverables. Confirm who will be responsible for design, pricing, site coordination and changes.'),('Make the commercial assumptions visible','Ask about inclusions, exclusions, review stages and how changes are agreed. A well-presented image should sit alongside a clear description of what will actually be provided.')],['Compare equivalent scopes and deliverables.','Verify references directly where appropriate.','Confirm responsibilities and change procedures before appointing anyone.'])
}
def classify(slug):
 rules=[('selection',r'designers|companies|hiring|find-office-interior'),('budget',r'cost|budget|affordable|roi'),('cultural',r'vastu|lucky|christmas|diwali|republic-day|new-year'),('ceiling',r'ceiling|gypsum|roof|\bpop\b'),('reception',r'reception|entrance|waiting'),('pantry',r'pantry|flooring'),('meetings',r'conference|meeting'),('acoustics',r'acoustic|sound|privacy'),('nature',r'plant|biophil|nature|greenery'),('colour',r'color|colour|pantone|paint'),('walls',r'wall|panel|tile|wallpaper'),('cabin',r'cabin|ceo|director|boss|md-room|chamber|partition|glass-door'),('furniture',r'furniture|chair|desk|table|furnishing|seating|cubicle'),('small',r'small|startup|space-efficient'),('flexible',r'hybrid|cowork|adapt|flexib|abw|desk-sharing'),('renovation',r'fit-out|renovation|turnkey|install|building-code'),('lighting',r'light'),('technology',r'\bai\b|technology|3d|tech-savvy'),('wellbeing',r'health|wellness|well-being|wellbeing|stress|inclusive|accessib|tranquil|happiness|gym'),('culture',r'culture|onboard|millennial|gen-z|gamification|work-life|employee|breakout'),('brand',r'brand|photograph'),('style',r'luxur|premium|minimal|industrial|wood|white|aesthetic|contemporary|modern-vs'),('planning',r'.')]
 return next(k for k,pat in rules if re.search(pat,slug))
def title_from(slug):
 s=slug.split('/')[-1];s=s.replace('to-wow-your-visitors','for-a-clear-first-impression');s=re.sub(r'officebanao','workplace',s);s=re.sub(r'-(copy|2)$','',s);s=s.replace('-',' ')
 s=re.sub(r'\b(20\d\d|2022s|\d+)\b','',s);s=re.sub(r'\b(stunning|amazing|ultimate|remarkable|outstanding|best|top|perfect|sleek|trendy|trending|most|wow|unleash|captivating)\b','',s)
 s=re.sub(r'\s+',' ',s).strip(' :');s=s.replace('fall ceiling','ceiling').replace('cas office','accounting office').replace('futuristic','future-ready').replace('prosperous and positive','personal')
 if 'designers' in s or 'companies' in s:
  city=re.search(r'(?:in|designers) (bangalore|noida|delhi|hyderabad|chennai|mumbai|india)',s)
  s='Choosing a workplace design partner'+(' in '+city.group(1).title() if city else '')
 if s.startswith(('how ','what ','why ')):s=s[0].upper()+s[1:]
 else:s=s[0].upper()+s[1:] if s else 'A considered workplace'
 s=re.sub(r'\bai\b','AI',s);s=re.sub(r'\b3d\b','3D',s);s=re.sub(r'\bpvc\b','PVC',s,flags=re.I);s=re.sub(r'\bceo\b','CEO',s)
 s=s.replace('a accounting','an accounting').replace('multi functional','multifunctional').replace('pop false','POP false').replace('maximum productivity','focused work').replace('revolutionizing','reshaping')
 s=re.sub(r'^(And |and )','',s)
 s=re.sub(r' (for|in|of|the|and|to)$','',s)
 s=re.sub(r' (for|in|of|the|and|to)$','',s)
 s=s.replace('How minimalist office interiors reshaping','How minimalist office interiors are reshaping').replace('an conference','a conference').replace('a startup offices','startup offices').replace('use brand identity into','bring brand identity into')
 for word,replacement in {'bangalore':'Bengaluru','gurgaon':'Gurugram','noida':'Noida','delhi':'Delhi','hyderabad':'Hyderabad','chennai':'Chennai','mumbai':'Mumbai','pune':'Pune','christmas':'Christmas','diwali':'Diwali','republic day':'Republic Day','ceo':'CEO','md':'MD','abw':'ABW','ai':'AI','roi':'ROI','gen z':'Gen Z'}.items():s=re.sub(r'\b'+word+r'\b',replacement,s,flags=re.I)
 if 'office interior design trends we can see' in s.lower():s='Office design trends worth considering'
 if 'open vs closed office interior designs choose' in s.lower():s='Open or enclosed: choosing your workplace settings'
 return s[0].upper()+s[1:].rstrip('.')+'.'

