for kind in ['page','post','myprojectlist','category','web-story']:
 urls=[x.text for x in ET.parse(WORK/('ob-'+kind+'.xml')).findall('.//{*}url/{*}loc')]
 source[kind]=[urlparse(u).path.strip('/') for u in urls]
