write('locations','Where are you making space?',crumb('Locations')+hero('PROJECT LOCATIONS','Start with your city.<br>Bring your brief.','Space Craft’s address is in Bengaluru. Use these location guides to frame a project conversation; availability elsewhere is confirmed for each brief.','light')+'<section class="section"><div class="eyebrow">EXPLORE BY LOCATION</div><h2>Different places.<br>The same starting question.</h2><p class="lead-copy narrow">What should your office help your team do? Choose a location to prepare the details that matter for a first conversation.</p><label class="search-label">Find a location<input type="search" data-search="location-cards" placeholder="Search city…"></label><div class="location-grid" id="location-cards">'+''.join(f'<a data-search-item href="/office-interior-designer-in-{c}/">{city_name(c)} <span>↗</span></a>' for c in sorted(cities))+'</div><p data-search-empty="location-cards" hidden>No matching location. You can still share your city through the contact page.</p></section>'+cta())
city_context={
'bangalore':('Plan for a changing team.','If your team combines office and remote work, discuss peak attendance alongside the average. Bring the building’s fit-out rules and a realistic schedule for decisions.'),
'mumbai':('Make every part of the footprint useful.','Compare the space needed for focused work, private calls, visitors and storage before fixing desk density. Review access, service condition and move logistics for the actual building.'),
'delhi':('Plan the visitor journey alongside the workday.','If client visits form part of your brief, consider reception, meeting access and confidentiality alongside the team’s everyday working settings.'),
'hyderabad':('Give growing teams room to change.','Identify which work settings need to stay fixed and which can adapt. Discuss how your attendance and collaboration patterns may change over time.'),
'chennai':('Think through materials and long-term care.','Ask how the proposed finishes will be cleaned, repaired and maintained in your building. Coordinate building services and material choices with the relevant specialists.'),
'pune':('Balance team space with focused work.','Map where project collaboration happens and where quieter settings are needed. Test furniture, storage and support spaces against a typical working day.'),
'gurgaon':('Connect the brief with the building.','Bring information about the existing fit-out, service provisions and any building approval process. Separate what is available from what needs to be added.'),
'noida':('Define the starting condition clearly.','Review the space as it exists, including partitions, services and furniture that may be retained. A clear scope makes later proposals easier to compare.')}
for i,c in enumerate(cities):
 city=city_name(c);angle,context=city_context.get(c,process[i%4][1:3]);title='A workplace brief for '+city+'.'
 b=crumb(city,('locations','Locations'))+hero('LOCATION GUIDE / '+city.upper(),'Make space.<br>In '+city+'.','Planning a workplace in '+city+'? Begin with the people, the space and the decisions your project needs.','studio' if i%2 else 'collaborate')+'<section class="section split-section"><div><div class="eyebrow">YOUR LOCAL BRIEF</div><h2>'+angle+'</h2></div><div><p class="lead-copy">'+context+'</p><p>For a project in '+city+', share the building location, approximate area, condition of the space and desired timeline. Delivery availability, scope and commercial terms need to be confirmed for the specific project.</p><p class="notice">Space Craft’s listed address is in Bengaluru. This guide does not claim an office, a delivery team or completed projects in '+city+'.</p></div></section><section class="section tone-paper"><div class="eyebrow">WHAT TO BRING</div>'+cards([('services/workplace-planning','The people.','Team size, peak attendance, work patterns and the spaces you currently miss.','01 / YOUR TEAM'),('services/interior-design','The place.','A plan, photos, building requirements and a sense of your visual priorities.','02 / YOUR SPACE'),('services/build-and-fit-out','The parameters.','Budget assumptions, decision makers, intended move date and any fixed constraints.','03 / YOUR BRIEF')])+'</section><section class="section split-section"><div><div class="eyebrow">TALK ABOUT '+city.upper()+'</div><h2>Tell us what<br>you have in mind.</h2><p>A demo inquiry creates a downloadable brief. Nothing is submitted.</p></div>'+form(location=city)+'</section>'
 write('office-interior-designer-in-'+c,title,b,'Location')

CONTEXT=[
 ('call-center|call-centre',('Plan for simultaneous conversations','A call-focused workplace has overlapping speech, equipment and different shift patterns to consider. Map team sizes, supervision, private escalation conversations and breaks. Review the balance of acoustic separation, operational visibility and the support areas people need between calls.')),
 ('law|advocate',('Keep confidential conversations on the plan','For a legal workplace, map the route from reception to a private meeting alongside the everyday team area. Think about document storage, visitor visibility and where sensitive calls may take place. Discuss speech privacy as a requirement rather than assuming an enclosed room automatically provides it.')),
 ('finance|cas-office|accounting',('Give confidential work an appropriate setting','Accounting and finance work may combine long periods of focused screen use with document review and private client conversations. Plan the storage, meeting access and screen positions together. Separate the visitor journey from places where confidential information may be visible.')),
 ('travel-office',('Design the consultation as a sequence','A travel-office brief can include arrival, a longer consultation, reviewing options on a shared screen and a private follow-up. Test the seating and screen position from both sides of the conversation. Provide a clear place for documents and customer belongings without crowding the work surface.')),
 ('advertising|architect-office',('Give project work somewhere to stay visible','Creative teams may need to gather around references, review work together and then return to concentration. Consider a project table, writable surfaces and the storage required for samples or models. Agree which work can remain on display and which needs to be secured.')),
 ('pvc',('Compare the actual ceiling product','A PVC finish should be evaluated using the proposed product and complete installation system. Ask for suitable application information, care instructions and the details of access and junctions. Review the physical sample alongside lighting and adjacent finishes before treating a catalogue image as the final result.')),
 ('gypsum',('Resolve access as well as appearance','For a gypsum ceiling proposal, ask where service access, joints, edges and lighting openings will be located. Review how the finished surface relates to partitions and any future changes. Have the specification and installation details checked for the actual building and intended use.')),
 ('wooden|wood-in',('Decide where the timber character belongs','Timber and timber-look finishes can appear very different across a large wall, a worktop and a small furniture detail. Compare samples at the intended scale and discuss cleaning, wear and replacement. Decide whether the finish is a background material or a deliberate point of emphasis.')),
 ('3d',('Use the visual to answer a specific question','A 3D view can help test proportions, sightlines or a material combination. Ask which elements are accurate and which are placeholders. Check the proposal against the measured plan and the product schedule so that the image remains a useful decision aid rather than an assumed construction specification.')),
 ('open-vs|open-office',('Compare the trade-offs of each setting','Open settings can make teams more visible to each other, while enclosed settings can provide separation for particular tasks. Compare the actual work patterns, privacy needs and support rooms before choosing a dominant layout. A mixture of settings may address the brief more clearly than an all-or-nothing choice.')),
 ('wallpaper|wall-tiles',('Review the junctions before committing','A patterned or modular wall finish needs an elevation as well as a sample. Look at the starting point, visible edges, corners, sockets and door surrounds. Test how the pattern reads from the entrance and from a seated position, then confirm care and replacement requirements.')),
 ('home-office',('Define the boundary around the working day','A home workspace has to fit alongside other uses of the room. Think about a stable workpoint, a suitable video-call background and a way to put equipment away. Test the lighting and sound at the times the setting will actually be used.')),
 ('storage|clutter',('Give the loose items a named home','List the things that currently accumulate on desks and shared surfaces. Separate everyday personal items from team equipment and occasional supplies. Place storage near the activity it supports and agree how shared cupboards will be labelled and kept useful.')),
 ('duration|timeline|process-duration',('Build a programme from dependencies','A project duration depends on the starting condition, approvals, scope, product lead times and the time needed for decisions. Ask for these assumptions to be shown in the programme. This planning note does not promise a standard completion time for every office.')),
 ('reception-table|reception-desk',('Test the desk from both sides','Review the reception workpoint alongside the visitor’s approach, reach and view. Include equipment, storage and cable routes in the drawing. An attractive front elevation should work with a practical setting for the person using the desk throughout the day.')),
 ('cost|budget|affordable',('Ask what the price actually includes','Compare proposals using a common scope and a clear list of assumptions. An occupied refurbishment, an empty shell and an office with reusable services can require very different work. No local price range is asserted in this note; a reliable estimate needs the actual brief and site information.')),
]
def contextual_section(slug):
 for pattern,section in CONTEXT:
  if re.search(pattern,slug):return section
 return None

# Articles: original topic-led planning notes with concrete design questions.
articles=[]
for slug in source['post']:
 key=classify(slug);topic,img,deck,sections,checks=TOPICS[key];title=title_from(slug)
 # Add a second relevant perspective instead of repeating a single generic body across every subject.
 secondary='budget' if any(w in slug for w in ['cost','budget','affordable']) else ('small' if 'small' in slug else ('brand' if any(w in slug for w in ['corporate','identity','brand']) else ('wellbeing' if 'productivity' in slug else 'planning')))
 sec=TOPICS[secondary][3][0]
 if sec in sections:sec=TOPICS['lighting' if key!='lighting' else 'furniture'][3][0]
 angle=title.rstrip('.').lower()
 intro=f'{deck} This Space Craft planning note looks at {E(angle)} through the choices that affect everyday use, the details worth testing and the questions to take into your project brief.'
 article_sections=sections+[sec]
 context=contextual_section(slug)
 if context:article_sections=[context]+article_sections
 toc='<nav class="article-toc" aria-label="On this page"><strong>IN THIS NOTE</strong>'+''.join(f'<a href="#point-{i}">{h}</a>' for i,(h,p) in enumerate(article_sections,1))+'<a href="#checklist">Before you decide</a></nav>'
 content=''.join(f'<section id="point-{i}"><span class="eyebrow">0{i} / DESIGN CONSIDERATION</span><h2>{h}</h2><p>{p}</p></section>' for i,(h,p) in enumerate(article_sections,1))
 related=[x for x in source['post'] if x!=slug and classify(x)==key][:3]
 b=crumb(topic,('blogs','Journal'))+f'<section class="article-heading section"><div class="eyebrow">SPACE CRAFT JOURNAL / {topic.upper()}</div><h1>{E(title)}</h1><p class="lead-copy">{intro}</p><div class="article-meta"><a href="/author/">Space Craft editorial</a><span>Planning note · 4 min read</span></div></section>'+photo(img,'Illustrative interior for a workplace design planning note','article-photo')+'<section class="section article-layout">'+toc+'<article class="article-content">'+content+'<section id="checklist" class="takeaway"><span class="eyebrow">BEFORE YOU DECIDE</span><h2>Take this into your brief.</h2><ul>'+''.join('<li>'+c+'</li>' for c in checks)+'</ul><p>Write down one priority, one constraint and one question you still need to answer. Review them beside the plan or material sample before agreeing the next design decision.</p></section><p class="article-disclaimer">General design considerations for discussion. Product suitability, technical performance, statutory requirements and project pricing need appropriate, project-specific review. Images are illustrative.</p></article></section><section class="section tone-paper"><div class="eyebrow">KEEP EXPLORING</div><h2>Another angle on your space.</h2>'+cards([(s,title_from(s),TOPICS[classify(s)][2],TOPICS[classify(s)][0]) for s in related])+'</section>'+cta('Turn an idea into a useful brief.')
 write(slug,title,b,'Journal','blogs',re.sub('<[^>]+>','',intro));articles.append({'path':slug,'title':title,'topic':topic,'image':img,'key':key,'description':deck})
