write('all-pages','Explore every part of Space Craft.',crumb('All pages')+'<section class="section directory"><div class="eyebrow">THE COMPLETE SITE</div><h1>Find your<br><em>next perspective.</em></h1><p class="lead-copy narrow">Explore company information, services, concept studies, location guides and the design library.</p><label class="search-label">Find a page<input type="search" data-search="page-directory" placeholder="Search by topic, city or page name…"></label><div id="page-directory">'+''.join('<section class="directory-group"><h2>'+kind+'</h2><div>'+''.join(f'<a data-search-item href="{E(r["path"])}">{E(r["title"])} <span>↗</span></a>' for r in records if r['kind']==kind)+'</div></section>' for kind in dict.fromkeys(r['kind'] for r in records))+'</div><p data-search-empty="page-directory" hidden>No matching page. Try another topic or a shorter search.</p></section>','Directory')
# Updated home shares real navigation and the supplied address.
home=(WORK/'home-before-subpages.html').read_text()
home=re.sub(r'<a class="skip".*?</header>\s*<div id="mobile-nav".*?</div>',header(),home,flags=re.S)
home=re.sub(r'<footer>.*?</footer>',footer(),home,flags=re.S)
home=home.replace('<link rel="stylesheet" href="style.css">','<link rel="stylesheet" href="/style.css"><link rel="stylesheet" href="/pages.css">').replace('src="assets/','src="/assets/').replace('src="app.js"','src="/app.js"')
home=home.replace('href="#contact"','href="/contact-us/"').replace('href="#spaces"','href="/projects/"')
home=home.replace('href="#process"','href="/how-we-work/"')
# Turn home concept buttons into links to the detailed studies; retain filtering.
for key,slug in [('focus','focus-and-flow'),('together','a-place-to-connect'),('flexible','room-to-grow')]:
 pattern=r'<button class="project([^\"]*)" data-category="'+key+r'" data-project="'+key+r'">(.*?)</button>'
 home=re.sub(pattern,lambda m:'<a class="project'+m.group(1)+'" data-category="'+key+'" href="/projects/'+slug+'/">'+m.group(2)+'</a>',home,flags=re.S)
home=home.replace('alt="Illustrative workplace: light-filled lounge with collaborative seating"','alt="Illustrative workplace: glass-fronted rooms beside a daylit circulation area"')
home=home.replace('alt="Illustrative relaxed team lounge with sofa seating"','alt="Illustrative office with glass partitions and an informal seating corner"')
home=home.replace('>space craft<span class="brand-dot">.</span>','><span class="wordmark-art"><img src="/assets/spacecraft-wordmark-v3.png" width="2172" height="724" alt="spacecraft"></span>').replace('Space Craft home','Spacecraft home')
home=home.replace('</head>','<link rel="canonical" href="'+BASE+'/"></head>')
(D/'index.html').write_text(home)
# Route coverage audit stored alongside authoring source.
actual={r['path'].strip('/') for r in records};mapped=[]
